function renderStats(){const e=document.getElementById("stats-grid");e&&"undefined"!=typeof FEDERATION_INFO&&(e.innerHTML=FEDERATION_INFO.quickStats.map(e=>`\n        <div class="stat-card">\n            <span class="stat-icon">${e.icon}</span>\n            <div class="stat-val">${e.value}</div>\n            <div class="stat-lbl">${e.label}</div>\n        </div>\n    `).join(""))}document.addEventListener("DOMContentLoaded",()=>{renderStats(),renderDisciplineFilters(),renderDisciplines(),renderAthletes(),renderRecords(),renderTimeline(),renderVenues(),renderReferences(),initThemeToggle(),initMobileMenu()});let activeDiscipline="all";function renderDisciplineFilters(){const e=document.getElementById("discipline-filter");if(!e||"undefined"==typeof DISCIPLINES)return;const n=DISCIPLINES.map(e=>`<button class="filter-btn" data-discipline="${e.category}">${e.icon} ${e.category}</button>`).join("");e.innerHTML='<button class="filter-btn active" data-discipline="all">All Disciplines</button>'+n,e.querySelectorAll(".filter-btn").forEach(n=>{n.addEventListener("click",()=>{activeDiscipline=n.dataset.discipline,e.querySelectorAll(".filter-btn").forEach(e=>e.classList.remove("active")),n.classList.add("active"),filterDisciplines()})})}function renderDisciplines(){const e=document.getElementById("disciplines-grid");e&&"undefined"!=typeof DISCIPLINES&&(e.innerHTML=DISCIPLINES.map(e=>`\n        <div class="discipline-card" data-category="${e.category}">\n            <span class="discipline-icon">${e.icon}</span>\n            <h3>${e.category}</h3>\n            <p>${e.description}</p>\n            <div class="event-tags">\n                ${e.events.map(e=>`<span class="event-tag">${e}</span>`).join("")}\n            </div>\n        </div>\n    `).join(""))}function filterDisciplines(){document.querySelectorAll(".discipline-card").forEach(e=>{"all"===activeDiscipline||e.dataset.category===activeDiscipline?e.classList.remove("hidden"):e.classList.add("hidden")})}function renderAthletes(){const e=document.getElementById("athletes-grid");e&&"undefined"!=typeof MAJOR_ATHLETES&&(e.innerHTML=MAJOR_ATHLETES.map(e=>`\n        <div class="athlete-card">\n            <div class="athlete-card-header">\n                <span class="athlete-name">🏆 ${e.name}</span>\n                <span class="athlete-discipline-tag">${e.discipline}</span>\n            </div>\n            <p><strong>Achievement:</strong> ${e.achievement}</p>\n            <p><strong>Federation Cup:</strong> ${e.federationCup}</p>\n            <div class="athlete-highlight">⭐ ${e.highlight}</div>\n        </div>\n    `).join(""))}function renderRecords(){const e=document.getElementById("records-grid");e&&"undefined"!=typeof RECORDS&&(e.innerHTML=RECORDS.map(e=>`\n        <div class="record-card">\n            <div class="record-event">🏅 ${e.event}</div>\n            <div class="record-value">${e.record}</div>\n            <div class="record-athlete">${e.athlete} (${e.year})</div>\n            <div class="record-note">${e.note} — Venue: ${e.venue}</div>\n        </div>\n    `).join(""))}function renderTimeline(){const e=document.getElementById("timeline-container");e&&"undefined"!=typeof TOURNAMENT_MILESTONES&&(e.innerHTML=TOURNAMENT_MILESTONES.map(e=>`\n        <div class="timeline-card">\n            <div class="timeline-year">${e.year}</div>\n            <div class="timeline-content">\n                <h3>${e.title}</h3>\n                <p>${e.description}</p>\n            </div>\n        </div>\n    `).join(""))}function renderVenues(){const e=document.getElementById("venues-grid");e&&"undefined"!=typeof VENUES&&(e.innerHTML=VENUES.map(e=>`\n        <div class="venue-card">\n            <div class="venue-location">📍 ${e.location}</div>\n            <h3>🏟️ ${e.name}</h3>\n            <p>${e.significance}</p>\n        </div>\n    `).join(""))}function renderReferences(){const e=document.getElementById("references-list");e&&"undefined"!=typeof REFERENCES&&(e.innerHTML=REFERENCES.map(e=>`\n        <li>\n            <a href="${e.link}" target="_blank" rel="noopener noreferrer">📚 ${e.text}</a>\n        </li>\n    `).join(""))}function initThemeToggle(){const e=document.getElementById("theme-toggle");if(!e)return;const n=localStorage.getItem("theme")||"dark";e.textContent="light"===n?"🌙":"☀️",e.addEventListener("click",()=>{const n=document.body.classList.toggle("light-theme");localStorage.setItem("theme",n?"light":"dark"),e.textContent=n?"🌙":"☀️"})}function initMobileMenu(){const e=document.getElementById("menu-toggle"),n=document.getElementById("nav-menu");e&&n&&e.addEventListener("click",()=>{const t="true"===e.getAttribute("aria-expanded");e.setAttribute("aria-expanded",String(!t)),n.classList.toggle("open")})}